func TestInvalidTOML(t *testing.T) {
  tests := []struct {
    name string
    toml string
  } {
    {
      name: "Non TOML raise an error",
      toml: "This is invalid toml!",
    },
    {
      name: "Rules with the same ID",
      toml: `[rule-1]
      instrument: true
      description: "test"
      expression = "runtime.language:java"

      [rule-1]
      instrument: true
      description: "test two"
      expression = "runtime.language:ruby"
      `,
    },
    {
      name: "type checking 1/x",
      toml: `[type-check-1]
      instrument = "yes"
      description = "ensure instrument is a boolean",
      expression = "runtime.language: c"
      `,
    },
    {
      name: "missing required field 1/x",
      toml: `[required-1]
      description = "missing instrument field"
      expression = "runtime.language:cpp"
      `,
    },
    {
      name: "missing required field 2/x",
      toml: `[required-2]
      description = "missing expression field"
      instrument = true
      `,
    },
    {
      name: "ill-formated expression 1/x",
      toml: `[empty-expr]
      description = "empty expression"
      instrument = true
      expression = ""
      `,
    },
    {
      name: "ill-formated expression 2/x",
      toml: `[invalid-expr]
      description = "format is k:v"
      instrument = true
      expression = "foo"
      `,
    },
    {
      name: "unknown selector",
      toml: `[unknown-selector]
      description = "unknown selector should raise an error"
      instrument = false
      expression = "foo:bar"
      `,
    },
  }

  log.SetOutput(io.Discard)

  for _, tt := range tests {
    t.Run(tt.name, func(t *testing.T) {
      _, err := run(tt.toml)
      assert.Error(t, err)
    })
  }
}

